#define CSR_MCAUSE_EXCEPTION_CODE_DESC       "This field is automatically updated with unique ID of the most recent exception or interrupt due to which CPU entered trap. Possible exception IDs are: 0x1: PMP instruction access fault 0x2: Illegal instruction 0x3: Hardware breakpoint/watchpoint or EBREAK 0x5: PMP load access fault 0x6: Misaligned store address or AMO address 0x7: PMP store access or AMO access fault 0x8: ECALL from U mode 0xb: ECALL from M mode Other values: reserved. Note: Exception ID 0x0 (instruction access misaligned) is not present because CPU always masks the lowest bit of the address during instruction fetch"
#define CSR_MCAUSE_EXCEPTION_CODE_SHIFT      ( 0 )
#define CSR_MCAUSE_EXCEPTION_CODE_MASK       ( 0x0000001F )
#define CSR_MCAUSE_EXCEPTION_CODE_VALUE(raw) ( ((raw) & (CSR_MCAUSE_EXCEPTION_CODE_MASK)) >> (CSR_MCAUSE_EXCEPTION_CODE_SHIFT) )
#define CSR_MCAUSE_EXCEPTION_CODE_RAW(value) ( (value) << (CSR_MCAUSE_EXCEPTION_CODE_SHIFT) )

#define CSR_MCAUSE_INTERRUPT_FLAG_DESC       "This flag is automatically updated when CPU enters trap. If this is found to be set, indicates that the latest trap occurred due to an interrupt. For exceptions it remains unset. Note: The interrupt controller is using up IDs in range 1-2, 5-6 and 8-31 for all external interrupt sources. This is different from the RISC-V standard which has reserved IDs in range 0-15 for core local interrupts only. Although local interrupt sources (CLINT) do use the reserved IDs 0, 3, 4 and 7"
#define CSR_MCAUSE_INTERRUPT_FLAG_SHIFT      ( 31 )
#define CSR_MCAUSE_INTERRUPT_FLAG_MASK       ( 0x80000000 )
#define CSR_MCAUSE_INTERRUPT_FLAG_VALUE(raw) ( ((raw) & (CSR_MCAUSE_INTERRUPT_FLAG_MASK)) >> (CSR_MCAUSE_INTERRUPT_FLAG_SHIFT) )
#define CSR_MCAUSE_INTERRUPT_FLAG_RAW(value) ( (value) << (CSR_MCAUSE_INTERRUPT_FLAG_SHIFT) )

