#define CSR_TCONTROL_MTE_DESC       "Configures whether to enable the machine mode trigger. When CPU is taking a machine mode trap, its value is automatically pushed into mpte, so this becomes 0 and triggers with action=0 are disabled globally. When CPU is executing MRET, the value of mpte is automatically popped back into this"
