#define CSR_TCONTROL_MPTE_DESC       "Configures whether to enable the machine mode previous trigger. When CPU is taking a machine mode trap, the value of mte is automatically pushed into this. When CPU is executing MRET, its value is popped back into mte, so this becomes 0"
#define CSR_TCONTROL_MPTE_SHIFT      ( 7 )
#define CSR_TCONTROL_MPTE_MASK       ( 0x00000080 )
#define CSR_TCONTROL_MPTE_VALUE(raw) ( ((raw) & (CSR_TCONTROL_MPTE_MASK)) >> (CSR_TCONTROL_MPTE_SHIFT) )
