#define CSR_DCSR_PRV_DESC       "Contains the privilege level the core was operating in when Debug Mode was entered. A debugger can change this value to change the core's privilege level when exiting Debug Mode. Only 0x3 (machine mode) and 0x0 (user mode) are supported"
#define CSR_DCSR_PRV_SHIFT      ( 0 )
#define CSR_DCSR_PRV_MASK       ( 0x00000003 )
#define CSR_DCSR_PRV_VALUE(raw) ( ((raw) & (CSR_DCSR_PRV_MASK)) >> (CSR_DCSR_PRV_SHIFT) )
#define CSR_DCSR_PRV_RAW(value) ( (value) << (CSR_DCSR_PRV_SHIFT) )

#define CSR_DCSR_STEP_DESC       "When set and not in Debug Mode, the core will only execute a single instruction and then enter Debug Mode. If the instruction does not complete due to an exception, the core will immediately enter Debug Mode before executing the trap handler, with appropriate exception registers set. Setting this bit does not mask interrupts"
#define CSR_DCSR_STEP_SHIFT      ( 2 )
#define CSR_DCSR_STEP_MASK       ( 0x00000004 )
#define CSR_DCSR_STEP_VALUE(raw) ( ((raw) & (CSR_DCSR_STEP_MASK)) >> (CSR_DCSR_STEP_SHIFT) )
#define CSR_DCSR_STEP_RAW(value) ( (value) << (CSR_DCSR_STEP_SHIFT) )

#define CSR_DCSR_CAUSE_DESC       "Explains why Debug Mode was entered. When there are multiple reasons to enter Debug Mode in a single cycle, the cause with the highest priority number is the one written. 1: An ebreak instruction was executed (priority 3) 2: The Trigger Module caused a halt (priority 4) 3: haltreq was set (priority 2) 4: The CPU core single stepped because step was set (priority 1) Other values are reserved"
#define CSR_DCSR_CAUSE_SHIFT      ( 6 )
